CREATE TEMPORARY VIEW vmodel AS
SELECT grass_region
    ,model_id
from paimon.srdi_mart.ods_sr_data_warehouse_vsku_model_mapping
where status=1
-- 剔除 live test 的vitem
and (case
       when grass_region='PH' then vitem_id not in (28220985573,25089553214,24439553114)
       when grass_region='TH' then vitem_id not in (25690469056,27623537795,29873533900)
       else true
end)
group by 1,2
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dwd_sr_data_warehouse_pb_one_variation_model_minf
PARTITION(grass_region, local_date, local_hour, regional_date,regional_hour, regional_minute)
select
     cspu_id
    ,cspu_tag
    ,a.model_id
    ,item_id
    ,shop_id
    ,business_type
    ,price
    ,if(b.model_id is not null, 1, 0) is_buybox

    ,a.grass_region
    ,date(date_timezone_convert(${regional_date},${regional_hour},'SG',a.grass_region,"yyyy-MM-dd")) as local_date
    ,cast(date_timezone_convert(${regional_date},${regional_hour},'SG',a.grass_region,"HH") as int) as local_hour
    ,cast(${regional_date} as date) as regional_date
    ,cast(${regional_hour} as int) as regional_hour
    ,cast(${regional_minute} as int) as regional_minute
from paimon.rcmd_feature.ods_sr_data_warehouse_pb_one_variation a
left join vmodel b
on a.grass_region = b.grass_region
and a.model_id = b.model_id
where a.model_id>0 -- =0 is deleted cheapest,which its cspu doesn't have cheapest model currently
and cspu_tag <> 8 -- 低质cspu，不能给SRA用的
;
